AND e.dept_id IN (
    WITH RECURSIVE dept_tree AS (
        SELECT dept_id FROM hrm_dept WHERE dept_id = #{rootDeptId}
        UNION ALL
        SELECT d.dept_id FROM hrm_dept d
        JOIN dept_tree dt ON d.parent_id = dt.dept_id
    )
    SELECT dept_id FROM dept_tree
)

AND d.dept_id IN (
    WITH RECURSIVE dept_tree AS (
        SELECT dept_id FROM hrm_dept WHERE dept_id = #{rootDeptId}
        UNION ALL
        SELECT d2.dept_id FROM hrm_dept d2
        JOIN dept_tree dt ON d2.parent_id = dt.dept_id
    )
    SELECT dept_id FROM dept_tree
)

mapper.select:
SELECT
    (SELECT COUNT(*) FROM hrm_employee e WHERE 
      AND e.dept_id = #{deptId}
      ) AS activeCount,
    (SELECT COUNT(*) FROM hrm_employee e
     WHERE e.is_del = 0 AND e.entry_time BETWEEN #{start} AND #{end}
      AND e.dept_id = #{deptId}
      ) AS hiredCount,
    (SELECT COUNT(*) FROM hrm_employee_quit_info q
      JOIN hrm_employee e ON e.employee_id = q.employee_id AND e.is_del = 0
      AND e.dept_id = #{deptId}

     WHERE COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time) BETWEEN #{start} AND #{end}) AS quitCount,
    (SELECT COUNT(*) FROM hrm_employee e WHERE e.is_del = 0 AND e.entry_status IN (1, 3) AND e.entry_time <= #{prevEnd}
      AND e.dept_id = #{deptId}
      ) AS prevActiveCount,
    (SELECT ROUND(AVG(TIMESTAMPDIFF(YEAR, e.date_of_birth, #{end})), 1) FROM hrm_employee e
      WHERE  AND e.date_of_birth IS NOT NULL
      AND e.dept_id = #{deptId}
      ) AS avgAge,
    (SELECT ROUND(AVG(TIMESTAMPDIFF(YEAR, e.entry_time, #{end})), 1) FROM hrm_employee e
      WHERE 
      AND e.dept_id = #{deptId}
      ) AS avgTenure
FROM DUAL

SELECT name, value FROM (
    SELECT d.name AS name,
           COUNT(CASE WHEN e.is_del = 0
                AND e.entry_status = #{entryStatus}
                AND e.entry_status IN (1, 3)
                AND e.entry_time <= #{end}
                AND e.sex = #{sex}
                AND e.highest_education = #{edu}
                AND 
                AND 
                AND e.dept_id IN (
                    WITH RECURSIVE dept_tree AS (
                        SELECT dept_id FROM hrm_dept WHERE dept_id = #{rootDeptId}
                        UNION ALL
                        SELECT d2.dept_id FROM hrm_dept d2
                        JOIN dept_tree dt ON d2.parent_id = dt.dept_id
                    )
                    SELECT dept_id FROM dept_tree
                )
           THEN 1 END) AS value
    FROM hrm_dept d
    LEFT JOIN hrm_employee e ON e.dept_id = d.dept_id
    WHERE d.dept_id = #{deptId}
    WHERE d.dept_id IN (
        WITH RECURSIVE dept_tree AS (
            SELECT dept_id FROM hrm_dept WHERE dept_id = #{rootDeptId}
            UNION ALL
            SELECT d2.dept_id FROM hrm_dept d2
            JOIN dept_tree dt ON d2.parent_id = dt.dept_id
        )
        SELECT dept_id FROM dept_tree
    )
    GROUP BY d.dept_id, d.name

    UNION ALL
    SELECT '未分配部门' AS name, COUNT(*) AS value
    FROM hrm_employee e
    WHERE e.is_del = 0
      AND e.entry_status = #{entryStatus}
      AND e.entry_status IN (1, 3)
      AND e.entry_time <= #{end}
      AND e.sex = #{sex}
      AND e.highest_education = #{edu}
      AND 
      AND 
      AND (e.dept_id IS NULL OR NOT EXISTS (SELECT 1 FROM hrm_dept d WHERE d.dept_id = e.dept_id))

) t
ORDER BY value DESC, name

SELECT DATE_FORMAT(e.entry_time, '${granule}') AS period, COUNT(*) AS cnt
FROM hrm_employee e
WHERE e.is_del = 0 AND e.entry_time BETWEEN #{start} AND #{end}
AND e.dept_id = #{deptId}

GROUP BY period
ORDER BY period

SELECT DATE_FORMAT(COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time), '${granule}') AS period,
       COUNT(*) AS cnt
FROM hrm_employee_quit_info q
JOIN hrm_employee e ON e.employee_id = q.employee_id AND e.is_del = 0
AND e.dept_id = #{deptId}

WHERE COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time) BETWEEN #{start} AND #{end}
AND q.quit_type = #{quitType}
GROUP BY period
ORDER BY period

SELECT COUNT(*)
FROM hrm_employee_quit_info q
JOIN hrm_employee e ON e.employee_id = q.employee_id AND e.is_del = 0
LEFT JOIN hrm_dept d ON d.dept_id = e.dept_id
JOIN hrm_key_post_config k ON k.post_name = e.post
WHERE COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time) BETWEEN #{start} AND #{end}
AND e.dept_id = #{deptId}

AND q.quit_type = #{quitType}

SELECT
    d.dept_id AS deptId,
    IFNULL(d.name, '未分配部门') AS deptName,
    (SELECT COUNT(*) FROM hrm_employee he
      WHERE he.is_del = 0 AND he.dept_id = d.dept_id
        AND he.entry_time BETWEEN #{start} AND #{end}
        AND he.dept_id IN (
            WITH RECURSIVE dept_tree AS (
                SELECT dept_id FROM hrm_dept WHERE dept_id = #{rootDeptId}
                UNION ALL
                SELECT d2.dept_id FROM hrm_dept d2
                JOIN dept_tree dt ON d2.parent_id = dt.dept_id
            )
            SELECT dept_id FROM dept_tree
        )) AS hired,
    (SELECT COUNT(*) FROM hrm_employee_quit_info q
      JOIN hrm_employee qe ON qe.employee_id = q.employee_id AND qe.is_del = 0 AND qe.dept_id = d.dept_id
      WHERE COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time) BETWEEN #{start} AND #{end}
      AND q.quit_type = #{quitType}
      AND qe.dept_id IN (
          WITH RECURSIVE dept_tree AS (
              SELECT dept_id FROM hrm_dept WHERE dept_id = #{rootDeptId}
              UNION ALL
              SELECT d2.dept_id FROM hrm_dept d2
              JOIN dept_tree dt ON d2.parent_id = dt.dept_id
          )
          SELECT dept_id FROM dept_tree
      )) AS quitCnt
FROM hrm_dept d
WHERE EXISTS (SELECT 1 FROM hrm_employee ae WHERE ae.dept_id = d.dept_id AND ae.is_del = 0)
AND d.dept_id IN (
    WITH RECURSIVE dept_tree AS (
        SELECT dept_id FROM hrm_dept WHERE dept_id = #{rootDeptId}
        UNION ALL
        SELECT d2.dept_id FROM hrm_dept d2
        JOIN dept_tree dt ON d2.parent_id = dt.dept_id
    )
    SELECT dept_id FROM dept_tree
)
ORDER BY deptName

SELECT * FROM ( SELECT 'in' AS recType, e.employee_id AS employeeId, e.employee_name AS employeeName, CASE e.sex WHEN 1 THEN '男' WHEN 2 THEN '女' ELSE '未知' END AS sex, IFNULL(d.name, '未分配部门') AS deptName, IFNULL(e.post, '') AS post, CASE WHEN e.date_of_birth IS NOT NULL THEN TIMESTAMPDIFF(YEAR, e.date_of_birth, e.entry_time) END AS age, AS highestEducation, NULL AS tenureYears, DATE_FORMAT(e.entry_time, '%Y-%m-%d') AS happenDate, CAST(NULL AS CHAR) AS quitTypeName, CAST(NULL AS CHAR) AS quitReasonName FROM hrm_employee e LEFT JOIN hrm_dept d ON d.dept_id = e.dept_id WHERE e.is_del = 0 AND e.entry_time BETWEEN #{start} AND #{end} AND e.dept_id = #{deptId}
UNION ALL SELECT 'quit' AS recType, e.employee_id AS employeeId, e.employee_name AS employeeName, CASE e.sex WHEN 1 THEN '男' WHEN 2 THEN '女' ELSE '未知' END AS sex, IFNULL(d.name, '未分配部门') AS deptName, IFNULL(e.post, '') AS post, CASE WHEN e.date_of_birth IS NOT NULL THEN TIMESTAMPDIFF(YEAR, e.date_of_birth, COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time)) END AS age, AS highestEducation, TIMESTAMPDIFF(YEAR, e.entry_time, COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time)) AS tenureYears, DATE_FORMAT(COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time), '%Y-%m-%d') AS happenDate, CASE q.quit_type WHEN 1 THEN '主动离职' WHEN 2 THEN '被动离职' ELSE '退休' END AS quitTypeName, CAST(q.quit_reason AS CHAR) AS quitReasonName FROM hrm_employee_quit_info q JOIN hrm_employee e ON e.employee_id = q.employee_id AND e.is_del = 0 LEFT JOIN hrm_dept d ON d.dept_id = e.dept_id WHERE COALESCE(q.salary_settlement_time, q.plan_quit_time, q.apply_quit_time) BETWEEN #{start} AND #{end} AND e.dept_id = #{deptId}
AND q.quit_type = #{quitType} ) t ORDER BY t.happenDate DESC, t.recType
